frameworks.vanilla:
// Mount and bind Area Chart Default
import ApexCharts from 'apexcharts';

const chartOptions = {
  "chart": {
    "type": "area",
    "height": "100%",
    "toolbar": {
      "show": false
    },
    "fontFamily": "inherit",
    "stacked": false
  },
  "colors": [
    "var(--chart-1)",
    "var(--chart-2)",
    "var(--chart-3)"
  ],
  "stroke": {
    "curve": "smooth",
    "width": 2
  },
  "fill": {
    "type": "gradient",
    "gradient": {
      "shadeIntensity": 1,
      "opacityFrom": 0.45,
      "opacityTo": 0.05,
      "stops": [
        0,
        100
      ]
    }
  },
  "grid": {
    "borderColor": "var(--color-border)",
    "strokeDashArray": 4
  },
  "xaxis": {
    "labels": {
      "style": {
        "colors": "var(--color-muted-foreground)"
      }
    },
    "axisBorder": {
      "color": "var(--color-border)"
    },
    "axisTicks": {
      "color": "var(--color-border)"
    }
  },
  "yaxis": {
    "labels": {
      "style": {
        "colors": "var(--color-muted-foreground)"
      }
    }
  },
  "tooltip": {
    "theme": "dark"
  }
};
const container = document.getElementById("area-default");
if (container) {
  const chartEl = container.querySelector("[data-chart-viewport]") || container;
  const chart = new ApexCharts(chartEl, chartOptions);
  chart.render();
}

frameworks.astro:
---
// AreaDefaultChart.astro
interface Props {
  title?: string;
  description?: string;
  class?: string;
}
const { title = "Area Chart Default", description = "Smooth curved single series area chart with vertical fill.", class: className = "" } = Astro.props;
---
<div id="area-default" class:list={["w-full", className]}>
  <div class="chart-container card p-6 flex flex-col gap-4 w-full" role="img" aria-label="Area Chart Default - Smooth curved single series area chart with vertical fill.">
  <div class="border-b border-border pb-3">
    <h3 class="text-base font-semibold">Area Chart Default</h3>
    <p class="text-sm text-muted-foreground">Smooth curved single series area chart with vertical fill.</p>
  </div>
  <div class="w-full aspect-[4/3] md:aspect-[16/9] lg:aspect-[2/1] min-h-[240px] relative flex items-center justify-center" data-chart-viewport>
    <svg class="h-48 w-full" viewBox="0 0 400 160" role="img" aria-label="Area Chart">
        <defs>
          <linearGradient id="grad-area-default" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="var(--chart-1)" stop-opacity="0.35"/>
            <stop offset="100%" stop-color="var(--chart-1)" stop-opacity="0.0"/>
          </linearGradient>
        </defs>
        <path d="M0,130 Q100,50 200,90 T400,30 L400,160 L0,160 Z" fill="url(#grad-area-default)"/>
        <path d="M0,130 Q100,50 200,90 T400,30" fill="none" stroke="var(--chart-1)" stroke-width="2.5"/>
      </svg>
    <div class="rounded-lg border border-border bg-background/95 p-2.5 text-xs shadow-xl backdrop-blur-sm flex flex-col gap-1 z-10" data-chart-tooltip>
    <span class="font-semibold text-muted-foreground">Series Overview</span>
    <div class="flex items-center gap-2">
      <span class="size-2 rounded-full" style="background-color: var(--chart-1)"></span>
      <span class="font-medium">Total: <strong class="tabular-nums font-semibold">$14,250.00</strong></span>
