  <div class="flex items-center justify-between border-t border-border pt-3 text-xs text-muted-foreground">
    <span>Series Total</span>
    <strong class="tabular-nums font-semibold text-foreground">$14,250.00</strong>
  </div>
</div>
</div>
<script>
  import ApexCharts from 'apexcharts';
  const chartOptions = {
  "chart": {
    "type": "area",
    "height": "100%",
    "toolbar": {
      "show": false
    },
    "fontFamily": "inherit",
    "stacked": false
  },
  "colors": [
    "var(--chart-1)",
    "var(--chart-2)",
    "var(--chart-3)"
  ],
  "stroke": {
    "curve": "smooth",
    "width": 2
  },
  "fill": {
    "type": "gradient",
    "gradient": {
      "shadeIntensity": 1,
      "opacityFrom": 0.45,
      "opacityTo": 0.05,
      "stops": [
        0,
        100
      ]
    }
  },
  "grid": {
    "borderColor": "var(--color-border)",
    "strokeDashArray": 4
  },
  "xaxis": {
    "labels": {
      "style": {
        "colors": "var(--color-muted-foreground)"
      }
    },
    "axisBorder": {
      "color": "var(--color-border)"
    },
    "axisTicks": {
      "color": "var(--color-border)"
    }
  },
  "yaxis": {
    "labels": {
      "style": {
        "colors": "var(--color-muted-foreground)"
      }
    }
  },
  "tooltip": {
    "theme": "dark"
  }
};
  const root = document.getElementById("area-default");
  if (root) {
    const chartEl = root.querySelector("[data-chart-viewport]") || root;
    const chart = new ApexCharts(chartEl, chartOptions);
    chart.render();
  }
</script>

