    "curve": "smooth",
    "width": 2
  },
  "fill": {
    "type": "gradient",
    "gradient": {
      "shadeIntensity": 1,
      "opacityFrom": 0.45,
      "opacityTo": 0.05,
      "stops": [
        0,
        100
      ]
    }
  },
  "grid": {
    "borderColor": "var(--color-border)",
    "strokeDashArray": 4
  },
  "xaxis": {
    "labels": {
      "style": {
        "colors": "var(--color-muted-foreground)"
      }
    },
    "axisBorder": {
      "color": "var(--color-border)"
    },
