        <path d="M0,130 Q100,50 200,90 T400,30 L400,160 L0,160 Z" fill="url(#grad-area-default)"/>
        <path d="M0,130 Q100,50 200,90 T400,30" fill="none" stroke="var(--chart-1)" strokeWidth="2.5"/>
      </svg>
    <div className="rounded-lg border border-border bg-background/95 p-2.5 text-xs shadow-xl backdrop-blur-sm flex flex-col gap-1 z-10" data-chart-tooltip>
    <span className="font-semibold text-muted-foreground">Series Overview</span>
    <div className="flex items-center gap-2">
      <span className="size-2 rounded-full" style={{ backgroundColor: "var(--chart-1)" }}></span>
      <span className="font-medium">Total: <strong className="tabular-nums font-semibold">$14,250.00</strong></span>
    </div>
