        </tr>
      </thead>
      <tbody>
        <tr>
          <td>Series 1</td>
          <td>Jan</td>
          <td>14,250</td>
        </tr>
        <tr>
          <td>Series 2</td>
          <td>Jan</td>
          <td>8,420</td>
        </tr>
      </tbody>
